(()=>{'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a;if(!document.querySelector('footer')||matchMedia('(display-mode: standalone)').matches)return;let promptEvent=null;const button=document.createElement('button');button.type='button';button.className='install-app-button';button.textContent=L('↓ Cài ứng dụng','↓ Install app');document.querySelector('footer').append(button);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptEvent=e;});window.addEventListener('appinstalled',()=>{button.remove();promptEvent=null;});button.onclick=async()=>{if(promptEvent){const e=promptEvent;promptEvent=null;await e.prompt();await e.userChoice;return;}document.getElementById('install-help')?.remove();const dialog=document.createElement('dialog');dialog.id='install-help';dialog.innerHTML='<h2>'+L('Cài HVAC Studio','Install HVAC Studio')+'</h2><p>'+L('Mở website bằng Chrome hoặc Edge. Chọn biểu tượng cài đặt trên thanh địa chỉ hoặc mục cài ứng dụng trong menu trình duyệt.','Open this website in Chrome or Edge. Use the install icon in the address bar or the app installation option in the browser menu.')+'</p><p>'+L('Ứng dụng mở trong cửa sổ riêng và cần kết nối Internet để tải các công cụ.','The app opens in its own window and requires an Internet connection to load the tools.')+'</p><button type="button" class="text-button">'+L('Đóng','Close')+'</button>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.showModal();};})();